const D={up:[0,1],down:[0,-1],left:[-1,0],right:[1,0]};
const Q={up:[-0.7071068,0,0,0.7071068],down:[0.7071068,0,0,0.7071068],right:[0,0,-0.7071068,0.7071068],left:[0,0,0.7071068,0.7071068]};
const pos=(c,r,y)=>[(c-1)*1.1,y,(1-r)*1.1];
const dist=s=>(2-s.c)+(2-s.r);
export function initialState(){return {c:0,r:0,moves:0,hint:null,msg:'',won:false};}
export function reduce({state,event}){
 if(event.type!=='action')return state;
 const s=Object.assign({},state);
 if(s.won)return s;
 const a=event.action;
 if(a==='hint'){s.hint=s.r<2?'up':(s.c<2?'right':null);s.msg='The green arrow shows a move one step closer to the goal.';return s;}
 const d=D[a];if(!d)return s;
 const c=s.c+d[0],r=s.r+d[1];
 if(c<0||c>2||r<0||r>2){s.msg='That move would leave the board, so nothing happened.';return s;}
 s.c=c;s.r=r;s.moves++;s.hint=null;s.msg='';
 if(c===2&&r===2){s.won=true;s.msg='You reached the goal in '+s.moves+' moves. The shortest route is 4 moves.'+(s.moves===4?' Perfect!':'');}
 return s;}
export function evaluate({state}){
 const s=state||initialState();
 const nodes={tok:{position:pos(s.c,s.r,0.4)}};
 if(s.hint){nodes.arrow={visible:true,position:pos(s.c,s.r,0.4),quaternion:Q[s.hint]};}else nodes.arrow={visible:false};
 const g=s.won?{status:'won',message:s.msg}:{status:'playing',message:s.msg||'Steps to goal: '+dist(s)+'. Move the token to the orange goal.'};
 return {nodes,materials:{goal:{color:s.won?'#f5b301':'#e8862a'}},readouts:{moves:s.moves,steps:dist(s)},goal:g};}
